INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(21677871, 'Gold Pride - Start Your Engines!', '黄金荣耀－启动引擎', 'GP－スタート・エンジン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把怪兽召唤·特殊召唤的场合，以那1只怪兽为对象才能发动。从卡组把3只「黄金荣耀」怪兽给对方观看，对方从那之中随机选1只。那1只怪兽在自己场上特殊召唤，剩余回到卡组。那之后，作为对象的怪兽破坏。'),
(91286284, 'Gold Pride - That Came Out of Nowhere!', '黄金荣耀－猛然袭来', 'GP－アウト・オブ・ノーウェア', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地把1只「黄金荣耀」怪兽特殊召唤。那之后，对方可以从自身的手卡·墓地把1只怪兽效果无效在自身场上特殊召唤。'),
(95283172, 'Gold Pride - The Crowd Goes Wild!', '黄金荣耀－欢腾激昂', 'GP－ゴー・ワイルド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡1只「黄金荣耀」怪兽给对方观看才能发动。和给人观看的怪兽卡名不同的1只「黄金荣耀」怪兽从卡组加入手卡。那之后，以下效果可以适用。 ●从手卡把1只「黄金荣耀」怪兽特殊召唤，自己失去那个原本攻击力数值的基本分。'),
(75500286, 'Gold Sarcophagus', '封印的黄金柜', '封印の黄金櫃', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组选1张卡除外。这张卡的发动后第2次的自己准备阶段，这个效果除外的卡加入手卡。'),
(78004197, 'Goldd, Wu-Lord of Dark World', '暗黑界的武神 高尔德', '暗黒界の武神 ゴルド', 'Effect Monster', 'Fiend', 'DARK', 5, 2300, 1400, '①：这张卡被效果从手卡丢弃去墓地的场合发动。这张卡特殊召唤。被对方的效果丢弃的场合，发动时可以以对方场上最多2张卡为对象。那个场合，再让以下效果适用。 ●作为对象的对方的卡破坏。'),
(95937545, 'Golden Allure Queen', '金色的魅惑女王', '金色の魅惑の女王', 'Link Monster', 'Spellcaster', 'DARK', NULL, 2500, NULL, '魔法师族怪兽3只 ①：这张卡连接召唤的场合才能发动。从自己的卡组·墓地把1只「魅惑的女王」怪兽特殊召唤，这张卡的攻击力直到下个回合的结束时上升1500。 ②：原本卡名包含「魅惑的女王」的自己怪兽持有的自身把怪兽装备的效果变成对方回合也能发动的效果。 ③：1回合1次，对方把效果发动时才能发动。场上1张卡破坏。这个回合中，自己场上的「魅惑的女王」怪兽不会被效果破坏。'),
(74029853, 'Golden Bamboo Sword', '金黄色的竹光', '黄金色の竹光', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「竹光」装备魔法卡存在的场合才能发动。自己从卡组抽2张。'),
(72283691, 'Golden Castle of Stromberg', '急流山的金宫', 'シュトロームベルクの金の城', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己准备阶段从卡组上面把10张卡里侧表示除外。不能除外的场合这张卡破坏。这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。把有「急流山的金宫」的卡名记述的1只怪兽从卡组特殊召唤。这个效果发动的回合，自己不能通常召唤。 ②：对方怪兽的攻击宣言时发动。那只攻击怪兽破坏，给与对方那个攻击力一半数值的伤害。'),
(93125329, 'Golden Cloud Beast - Malong', '金云兽－马龙', '金雲獣－馬龍', 'Synchro Tuner Monster', 'Dragon', 'LIGHT', 6, 2200, 1000, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。这张卡的等级上升或下降1星。 ②：这张卡被送去墓地的场合，以对方场上1张表侧表示卡为对象才能发动。那张卡回到手卡。'),
(28565527, 'Golden Dragon Summoner', '黄龙召唤士', '黄龍の召喚士', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1000, 1000, '「黄龙召唤士」的效果1回合只能使用1次。 ①：把自己场上1只怪兽解放，以场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。'),
(76203291, 'Golden Flying Fish', '光鳞飞鱼', '光鱗のトビウオ', 'Effect Monster', 'Fish', 'LIGHT', 4, 1700, 1000, '把自己场上存在的这张卡以外的1只鱼族怪兽解放发动。场上1张卡破坏。'),
(59156966, 'Golden Gearbox', '黄金齿车装置箱', '黄金の歯車装置箱', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只名字带有「机巧」的怪兽发动。直到结束阶段时，选择的怪兽的攻击力上升500，守备力上升1500。'),
(27408609, 'Golden Homunculus', '黄金人工生命体', '黄金のホムンクルス', 'Effect Monster', 'Warrior', 'LIGHT', 6, 1500, 1500, '这张卡的攻击力·守备力上升从游戏中除外的自己的卡数量×300的数值。'),
(87102774, 'Golden Ladybug', '黄金瓢虫', '黄金の天道虫', 'Effect Monster', 'Insect', 'LIGHT', 1, NULL, NULL, '自己的准备阶段时，可以把手卡的这张卡给对方玩家观看，自己回复500基本分。这个效果使用的场合，直到结束阶段时把手卡的这张卡公开。这个效果1回合只能使用1次。'),
(56984514, 'Golden Land Forever!', '永恒闪耀的黄金乡', '永久に輝けし黄金郷', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「黄金国巫妖」怪兽存在，怪兽的效果·魔法·陷阱卡发动时，把自己场上1只不死族怪兽解放才能发动。那个发动无效并破坏。'),
(3574681, 'Golden Rule', '金科玉条', '金科玉条', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「宝玉」卡使用。这个卡名的卡在1回合只能发动1张。 ①：从卡组选2只「宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。那之后，从自己的手卡·墓地选和放置的卡卡名不同的1只「宝玉兽」怪兽特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。'),
(78642798, 'Golden-Eyes Idol', '黄金邪教神', '黄金の邪教神', 'Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己·对方回合1次，可以发动。对方手卡全部确认。这张卡的卡名直到结束阶段当作「千眼邪教神」使用。 ②：这张卡被除外的场合或者被效果送去墓地的场合，以对方场上1只效果怪兽为对象才能发动。那只效果怪兽给自己场上1只不能通常召唤的「纳祭」怪兽装备。只要这个效果把怪兽装备中，装备怪兽的攻击力上升那个攻击力数值。'),
(81344070, 'Goldenhair, the Newest Plunder Patroll', '海造贼-金头发训练生', '海造賊－金髪の訓練生', 'Tuner Monster', 'Fiend', 'WATER', 4, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：从这张卡以外的手卡以及自己场上的表侧表示的卡之中把1张「海造贼」怪兽卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡在墓地存在的场合，丢弃1张手卡才能发动。这张卡特殊召唤。这个回合，自己不是「海造贼」怪兽不能特殊召唤。'),
(24521754, 'Goldilocks the Battle Landscaper', '百景战都 金发姑娘城', '百景戦都ゴルディロックス', 'Effect Monster', 'Machine', 'EARTH', 10, NULL, 3000, '①：这张卡往中央以外的主要怪兽区域召唤·特殊召唤的场合破坏。 ②：只要这张卡在主要怪兽区域的中央存在，这张卡的攻击力上升3000。 ③：1回合1次，指定没有使用的自己的主要怪兽区域1处才能发动。自己的主要怪兽区域的这张卡的位置向指定的区域移动。那之后，和移动前与移动后的怪兽区域以及那些中间的怪兽区域相同纵列存在的除这张卡以外的卡全部破坏。'),
(9666558, 'Golem Dragon', '石龙', 'ゴーレム・ドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 4, 200, 2000, '只要这张卡在场上表侧表示存在，对方不能选择表侧表示存在的其他的龙族怪兽作为攻击对象。'),
(52323207, 'Golem Sentry', '番兵石人', '番兵ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 4, 800, 1800, '这张卡1回合1次，可以变成里侧守备表示。这张卡反转召唤成功时，选择对方1只怪兽回到持有者手卡。'),
(74169516, 'Golem that Guards the Millennium Treasures', '守护仟年之宝的魔像', '千年の宝を守りしゴーレム', 'Effect Monster', 'Rock', 'EARTH', 6, 2000, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。这张卡当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续魔法卡使用的场合，支付2000基本分或把手卡1张「千年十字」给对方观看才能发动。这张卡特殊召唤。那之后，可以从卡组把1张「石版神殿」加入手卡。 ③：只要这张卡在怪兽区域存在，自己的「千年十字」的发动不会被无效化。'),
(7526150, 'Golgoil', '戈鲁戈伊尔', 'ゴルゴイル', 'Normal Monster', 'Machine', 'EARTH', 4, 900, 1600, '从与异次元相通的洞里出来的钢铁大魔人。'),
(59369430, 'Golgoil the Steel Seismic Smasher', '钢铁大魔人 戈鲁戈伊尔', '鋼鉄の大魔人ゴルゴイル', 'Effect Monster', 'Illusion', 'EARTH', 10, 1800, 3200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ②：自己的机械族·幻想魔族怪兽进行战斗的伤害计算后，以自己的墓地·除外状态的1只怪兽为对象才能发动。那只怪兽特殊召唤。 ③：这张卡从场上除外的场合才能发动。这张卡特殊召唤。'),
(59797187, 'Gonogo', '滚滚球', 'ゴロゴル', 'Effect Monster', 'Rock', 'EARTH', 3, 1350, 1600, '和这张卡进行战斗的对方怪兽在伤害步骤结束时变成里侧守备表示。'),
(62835876, 'Good & Evil in the Burning Abyss', '善恶的彼岸', '善悪の彼岸', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「彼岸的鬼神 马拉布兰卡」的降临必需。「善恶的彼岸」的②的效果1回合只能使用1次。 ①：从自己的手卡·场上把等级合计直到6以上的怪兽解放，从手卡把「彼岸的鬼神 马拉布兰卡」仪式召唤。 ②：自己主要阶段把墓地的这张卡除外，从手卡把1只「彼岸」怪兽送去墓地才能发动。从卡组把1张「彼岸」卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(9744376, 'Good Goblin Housekeeping', '哥布林的经营手腕', 'ゴブリンのやりくり上手', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组抽自己墓地存在的「哥布林的经营手腕」的数量＋1的卡，选择1张手卡放回到卡组最下面。'),
(77799846, 'Googly-Eyes Drum Dragon', '废品眼太鼓龙', '廃品眼の太鼓竜', 'XYZ Monster', 'Machine', 'EARTH', 8, 3000, 2500, '机械族8星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力直到下次的对方的结束阶段时上升1000。持有超量素材的这张卡被破坏的场合，可以通过把自己墓地1只名字带有「超级防卫机器人」的怪兽从游戏中除外，这张卡从墓地特殊召唤。那之后，可以选自己墓地1只名字带有「超级防卫机器人」的怪兽在这张卡下面重叠作为超量素材。'),
(80233946, 'Gora Turtle', '筮龟', 'ゴラ・タートル', 'Effect Monster', 'Aqua', 'WATER', 3, 1100, 1100, '只要这张卡在场上表侧表示存在，攻击力1900以上的怪兽不能进行攻击宣言。'),
(42868711, 'Gora Turtle of Illusion', '幻影筮龟', '幻影のゴラ亀', 'Effect Monster', 'Aqua', 'WATER', 4, 1200, 1400, '以场上表侧表示的这张卡为对象的，由对方所控制的魔法·陷阱卡的效果无效。'),
(66236707, 'Gordian Slicer', '械刀婪魔皇断', '械刀婪魔皇断', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的发动和效果不会被无效化。 ①：自己的主要阶段1·主要阶段2的开始时，以场上的表侧表示卡任意数量为对象才能发动。作为对象的卡每有1张，自己1张手卡或自己的额外卡组6张卡里侧除外。那之后，作为对象的卡回到手卡。'),
(11793047, 'Gorgon Egg', '戈耳工蛋', 'ゴーゴン・エッグ', 'Normal Monster', 'Fiend', 'DARK', 3, 300, 1300, '蛇发女所产下的巨卵。其他一切资料不详。'),
(12067160, 'Gorgon of Zilofthonia', '美丽的磁律机坏', '麗しき磁律機壊', 'Link Monster', 'Reptile', 'DARK', NULL, 100, NULL, '效果怪兽2只以上 自己不能在这张卡所连接区让怪兽出现。 ①：这张卡所连接区的怪兽不能攻击，那些怪兽的所发动的效果无效化。 ②：这张卡的攻击力上升这张卡所连接区的怪兽的原本攻击力数值。 ③：这张卡所连接区没有怪兽存在的场合，这张卡不会被战斗以及怪兽的效果破坏。'),
(29357687, 'Gorgon, Empress of the Evil Eyed', '咒眼之女王 戈耳戈涅', '呪眼の女王 ゴルゴーネ', 'Link Monster', 'Fiend', 'DARK', NULL, 1900, NULL, '包含「咒眼」怪兽的怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升自己墓地的「咒眼」卡种类×100。 ②：这张卡有「太阴之咒眼」装备的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。 ③：这张卡的②的效果发动的场合，下次的准备阶段发动。选这张卡所连接区1只怪兽破坏。'),
(52648457, 'Gorgon''s Eye', '戈耳工之眼', 'ゴーゴンの眼', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '结束阶段结束前，场上存在的守备表示的怪兽的效果无效化。'),
(37168514, 'Gorgonic Cerberus', '蛇头地狱犬', 'ゴルゴニック・ケルベロス', 'Effect Monster', 'Rock', 'DARK', 3, 1300, 300, '这张卡召唤成功时，可以让自己场上的全部岩石族怪兽的等级变成3星。'),
(64379261, 'Gorgonic Gargoyle', '蛇头石像怪', 'ゴルゴニック・ガーゴイル', 'Effect Monster', 'Rock', 'DARK', 3, 1000, 800, '自己对岩石族怪兽的召唤成功时，这张卡可以从手卡特殊召唤。'),
(90764875, 'Gorgonic Ghoul', '蛇头食尸鬼', 'ゴルゴニック・グール', 'Effect Monster', 'Rock', 'DARK', 1, 100, 100, '自己场上有「蛇头食尸鬼」存在的场合，支付300基本分才能发动。这张卡从手卡特殊召唤。「蛇头食尸鬼」的效果1回合可以使用最多2次。'),
(37984162, 'Gorgonic Golem', '蛇头石人', 'ゴルゴニック・ゴーレム', 'Effect Monster', 'Rock', 'DARK', 3, 1200, 600, '这张卡被战斗破坏送去墓地时，让把这张卡破坏的怪兽的攻击力变成0。此外，自己的主要阶段时，把墓地的这张卡从游戏中除外，选择对方场上盖放的1张魔法·陷阱卡才能发动。这个回合，选择的卡不能发动。对方不能对应这个效果的发动把选择的卡发动。'),
(84401683, 'Gorgonic Guardian', '蛇魔・守护者', 'ゴルゴニック・ガーディアン', 'XYZ Monster', 'Rock', 'DARK', 3, 1600, 1200, '岩石族3星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择对方场上表侧表示存在的1只怪兽才能发动。直到回合结束时，选择的怪兽的攻击力变成0，那个效果无效。这个效果在对方回合也能发动。此外，1回合1次，选择场上1只攻击力是0的怪兽才能发动。选择的怪兽破坏。'),
(44330098, 'Gorz the Emissary of Darkness', '冥府之使者格斯', '冥府の使者ゴーズ', 'Effect Monster', 'Fiend', 'DARK', 7, 2700, 2500, '自己场上没有卡存在的场合，因对方控制的卡受到伤害时，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功时，把受到的伤害种类的以下效果发动。 ●战斗伤害的场合，在自己场上把1只「冥府之使者 凯恩衍生物」（天使族·光·7星·攻/守?）特殊召唤。这衍生物的攻击力·守备力变成和这个时候受到的战斗伤害相同的数值。 ●卡的效果伤害的场合，给与对方基本分和受到的伤害相同的伤害。'),
(91148083, 'Gotterdammerung', '诸神的黄昏', '神々の黄昏', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「极神」的怪兽发动。选择的怪兽的控制权转移给对方。下次的对方的结束阶段时，选择的怪兽破坏，对方场上存在的卡全部从游戏中除外。'),
(13504844, 'Gottoms'' Emergency Call', '加特姆士的紧急指令', 'ガトムズの緊急指令', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有「X-剑士」怪兽存在的场合，以自己·对方的墓地的「X-剑士」怪兽合计2只为对象才能发动。那2只怪兽在自己场上特殊召唤。'),
(61948106, 'Gottoms'' Second Call', '加特姆士的紧急召集', 'ガトムズの非常召集', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能进行战斗阶段。 ①：自己场上有「X-剑士」同调怪兽存在的场合，以自己墓地2只「X-剑士」怪兽为对象才能发动。那2只怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽攻击力变成0，这个回合的结束阶段破坏。'),
(12097275, 'Gouki Bearhug', '刚鬼 抱熊', '剛鬼ハッグベア', 'Effect Monster', 'Warrior', 'EARTH', 6, 2400, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤或者用「刚鬼」卡的效果特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成原本攻击力的一半。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 熊抱熊精」以外的1张「刚鬼」卡加入手卡。'),
(85638822, 'Gouki Cage Match', '刚鬼死斗', '剛鬼死闘', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，给这张卡放置3个指示物。 ②：自己的「刚鬼」怪兽战斗破坏对方怪兽的场合发动。这张卡1个指示物取除。 ③：这张卡的效果给这张卡放置的指示物全部被取除的战斗阶段结束时才能由自己把这个效果发动。从手卡·卡组把「刚鬼」怪兽尽可能特殊召唤（同名卡最多1张）。那之后，给这张卡放置3个指示物。'),
(88406570, 'Gouki Destroy Ogre', '刚鬼 覆灭食人魔', '剛鬼デストロイ・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2800, NULL, '「刚鬼」怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡所连接区的怪兽在1回合各有1次不会被战斗破坏。 ②：自己主要阶段才能发动。对方从自身墓地选最多2只怪兽特殊召唤。那之后，自己从自己墓地选最多有特殊召唤的怪兽数量的连接怪兽以外的「刚鬼」怪兽在这张卡所连接区特殊召唤。这个效果的发动后，直到回合结束时自己不是「刚鬼」怪兽不能特殊召唤。'),
(69453825, 'Gouki Dragon Ogre', '刚鬼 龙食人魔', '剛鬼ドラゴン・オーガ', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2200, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把1张「刚鬼」魔法卡加入手卡。 ②：这张卡被送去墓地的场合，以自己场上1只地属性怪兽为对象才能发动。比那只怪兽攻击力低的1只「刚鬼」怪兽从自己墓地加入手卡。只要作为对象的怪兽在自己场上表侧表示存在，对方怪兽只能选择作为对象的怪兽作为攻击对象。'),
(26285557, 'Gouki Face Turn', '刚鬼弃暗投明', '剛鬼フェイスターン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1张「刚鬼」卡和自己墓地1只「刚鬼」怪兽为对象才能发动。作为对象的场上的卡破坏，作为对象的墓地的怪兽特殊召唤。'),
(35870016, 'Gouki Finishing Move', '刚鬼必杀技', '剛鬼フィニッシュホールド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「刚鬼」连接怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升那个连接标记数量×1000，这个回合那只怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。这张卡的发动后，直到回合结束时自己不用「刚鬼」怪兽不能攻击宣言。'),
(95448372, 'Gouki Gameface', '刚鬼斗魂', '剛鬼闘魂', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从手卡把1只4星以下而战士族·恐龙族·电子界族的地属性怪兽守备表示特殊召唤。 ②：把自己场上1只连接3以上的「刚鬼」怪兽解放才能发动。从卡组·额外卡组把1只「恐龙摔跤手」怪兽或「G石人」怪兽特殊召唤。'),
(7540107, 'Gouki Guts', '刚鬼 胆识', '剛鬼ガッツ', 'Effect Monster', 'Warrior', 'EARTH', 1, 800, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：守备表示的这张卡不会被战斗破坏。 ②：自己主要阶段才能发动。自己场上的全部「刚鬼」怪兽的攻击力上升200。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 毅力鬼」以外的1张「刚鬼」卡加入手卡。'),
(54088068, 'Gouki Headbatt', '刚鬼 头锤蝙蝠', '剛鬼ヘッドバット', 'Effect Monster', 'Warrior', 'EARTH', 2, 800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡的场合，把这张卡以外的1只「刚鬼」怪兽从手卡送去墓地，以自己场上1只「刚鬼」怪兽为对象才能发动。这张卡从手卡守备表示特殊召唤，作为对象的怪兽的攻击力直到回合结束时上升800。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 头锤蝙蝠」以外的1张「刚鬼」卡加入手卡。'),
(10552026, 'Gouki Heel Ogre', '刚鬼 邪道食人魔', '剛鬼ジャドウ・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 1000, NULL, '「刚鬼」怪兽2只 ①：1回合1次，这张卡所连接区的怪兽的效果发动时才能发动。那个发动无效并破坏。那之后，可以从自己墓地选「刚鬼 邪道食人魔」以外的1只「刚鬼」怪兽特殊召唤。'),
(71555408, 'Gouki Iron Claw', '刚鬼 铁爪', '剛鬼アイアン・クロー', 'Effect Monster', 'Warrior', 'EARTH', 2, 1000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「刚鬼」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只自己怪兽直到回合结束时攻击力上升500，不受对方的效果影响。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 铁爪手」以外的1张「刚鬼」卡加入手卡。'),
(59644128, 'Gouki Jet Ogre', '刚鬼 喷气食人魔', '剛鬼ジェット・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2000, NULL, '「刚鬼」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，以自己场上1张「刚鬼」卡为对象才能发动。那张卡破坏，场上的怪兽全部变成表侧攻击表示。 ②：这张卡从场上送去墓地的场合才能发动。自己场上的全部「刚鬼」怪兽的攻击力直到回合结束时上升500。'),
(29099860, 'Gouki Machine Suprex', '刚鬼 魔神・过肩摔霸王龙', '剛鬼マシン・スープレックス', 'Tuner Monster', 'Warrior', 'EARTH', 4, 1800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡和手卡1只「刚鬼」怪兽给对方观看才能发动。那2只特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是「刚鬼」怪兽不能特殊召唤。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 魔神风车过肩摔霸王龙」以外的1张「刚鬼」卡加入手卡。'),
(20191720, 'Gouki Moonsault', '刚鬼 月面压击', '剛鬼ムーンサルト', 'Effect Monster', 'Warrior', 'EARTH', 6, 1900, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看，以「刚鬼 月面坠击兔」以外的自己场上1只「刚鬼」怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到持有者手卡。 ②：以自己墓地1只「刚鬼」连接怪兽为对象才能发动。那只怪兽回到额外卡组。那之后，可以从自己墓地选1只「刚鬼」怪兽加入手卡。'),
(85008676, 'Gouki Octostretch', '刚鬼 固定章鱼', '剛鬼マンジロック', 'Effect Monster', 'Warrior', 'EARTH', 1, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：对方怪兽攻击的场合，那次伤害计算时把这张卡从手卡丢弃才能发动。那次战斗发生的对自己的战斗伤害变成一半。 ②：给与自己伤害的效果由对方发动时，把这张卡从手卡丢弃才能发动（伤害步骤也能发动）。那个效果让自己受到的伤害变成一半。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 锁臂章鱼」以外的1张「刚鬼」卡加入手卡。'),
(62376646, 'Gouki Re-Match', '刚鬼再战', '剛鬼再戦', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地2只等级不同的「刚鬼」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。'),
(93581434, 'Gouki Ringtrainer', '刚鬼 地狱训练师', '剛鬼ヘルトレーナー', 'Effect Monster', 'Warrior', 'EARTH', 1, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，把手卡的这张卡给对方观看，以自己墓地1只「刚鬼」连接怪兽为对象才能发动。这张卡从手卡特殊召唤。那之后，作为对象的怪兽特殊召唤。这个效果特殊召唤的连接怪兽攻击力下降500。 ②：只要自己场上有「刚鬼」连接怪兽存在，这张卡不会被战斗破坏。'),
(60461077, 'Gouki Riscorpio', '刚鬼 闪踢蝎', '剛鬼ライジングスコーピオ', 'Effect Monster', 'Warrior', 'EARTH', 5, 2300, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽不存在的场合或者只有「刚鬼」怪兽的场合，这张卡可以不用解放作召唤。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 闪光斧踢蝎」以外的1张「刚鬼」卡加入手卡。'),
(7382007, 'Gouki Sheik Ogre', '刚鬼 酋长食人魔', '剛鬼シーク・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 1900, NULL, '「刚鬼」怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：「刚鬼」怪兽用抽卡以外的方法从卡组加入自己手卡的场合才能发动。从手卡把「刚鬼」怪兽任意数量特殊召唤（相同等级最多1只）。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是「刚鬼」怪兽不能特殊召唤。 ②：自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「刚鬼」融合怪兽融合召唤。'),
(24073068, 'Gouki Suprex', '刚鬼 过肩摔霸王龙', '剛鬼スープレックス', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从手卡把1只「刚鬼」怪兽特殊召唤。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 过肩摔霸王龙」以外的1张「刚鬼」卡加入手卡。'),
(67586735, 'Gouki Tagpartner', '刚鬼 合力攻击', '剛鬼ツープラトン', 'Effect Monster', 'Warrior', 'EARTH', 5, 1700, NULL, '①：这张卡作为「刚鬼」连接怪兽的连接素材送去墓地的场合才能发动。那只「刚鬼」连接怪兽的攻击力直到回合结束时上升1000。 ②：把墓地的这张卡除外，以自己墓地1张「刚鬼」魔法卡为对象才能发动。那张卡回到卡组。这个效果在这张卡送去墓地的回合不能发动。'),
(95515058, 'Gouki The Blade Ogre', '刚鬼 持剑食人魔', '剛鬼ザ・ブレード・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2400, NULL, '「刚鬼」怪兽2只以上 ①：这张卡的攻击力上升这张卡所连接区的怪兽数量×300。 ②：1回合1次，把这张卡所连接区1只自己或者对方的怪兽解放才能发动。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(47946130, 'Gouki The Giant Ogre', '刚鬼 巨人食人魔', '剛鬼ザ・ジャイアント・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 3000, NULL, '「刚鬼」怪兽3只以上 ①：场上的这张卡不会被战斗破坏，不受持有这张卡的攻击力以下的攻击力的对方怪兽的所发动的效果影响。 ②：以场上的这张卡或者这张卡所连接区的怪兽为对象的对方的效果发动时才能发动。这张卡的攻击力下降500，那个发动无效。 ③：1回合1次，这张卡的攻击力和原本攻击力不同的场合才能发动。这张卡的攻击力直到回合结束时上升1000。这个效果在对方回合也能发动。'),
(78437364, 'Gouki The Great Ogre', '刚鬼 巨型食人魔', '剛鬼ザ・グレート・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2600, NULL, '「刚鬼」怪兽2只以上 ①：只要这张卡在怪兽区域存在，场上的怪兽的攻击力下降那怪兽的原本守备力数值。 ②：这张卡被战斗·效果破坏的场合，可以作为代替把这张卡所连接区1只自己怪兽破坏。'),
(30286474, 'Gouki The Master Ogre', '刚鬼 大师食人魔', '剛鬼ザ・マスター・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2800, NULL, '「刚鬼」怪兽2只以上 ①：1回合1次，让这张卡所连接区的自己的「刚鬼」怪兽任意数量回到持有者手卡，以回到手卡的数量的对方场上的表侧表示的卡为对象才能发动。那些卡的效果直到回合结束时无效。这个效果在对方回合也能发动。 ②：这张卡可以向对方怪兽全部各作1次攻击，对方场上有表侧表示怪兽存在的场合，只能选择那之内的攻击力最高的怪兽作为攻击对象。'),
(11516241, 'Gouki The Powerload Ogre', '刚鬼 力道食人魔', '剛鬼ザ・パワーロード・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2800, NULL, '战士族怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡以外的自己场上的连接怪兽的连接标记合计×200。 ②：连接召唤的这张卡不受其他卡的效果影响。 ③：把自己场上1只「刚鬼」连接怪兽解放，以最多有那个连接标记数量的场上的卡为对象才能发动。那些卡破坏。'),
(22510667, 'Gouki The Solid Ogre', '刚鬼 铠甲食人魔', '剛鬼ザ・ソリッド・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2400, NULL, '「刚鬼」怪兽2只以上 ①：只要这张卡所连接区有「刚鬼」怪兽存在，这张卡不会被战斗·效果破坏。 ②：1回合1次，以「刚鬼 硬铠食人魔」以外的自己的主要怪兽区域1只「刚鬼」怪兽为对象才能发动。那只自己怪兽的位置向作为这张卡所连接区的自己的主要怪兽区域移动。这个效果在对方回合也能发动。'),
(7782069, 'Gouki The Tyrant Ogre', '刚鬼 暴君食人魔', '剛鬼ザ・タイラント・オーガ', 'Fusion Monster', 'Warrior', 'EARTH', 8, 3500, NULL, '「刚鬼」连接怪兽＋战士族·恐龙族·电子界族怪兽 这个卡名的①的效果1回合只能使用1次。 ①：这张卡融合召唤的场合，以最多有那些作为融合素材的「刚鬼」连接怪兽的连接标记合计数量的场上的卡为对象才能发动（连接3以上的怪兽为融合素材的场合，不能对应这个发动把作为对象的卡的效果发动）。那些卡破坏。 ②：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(30010480, 'Gouki Thunder Ogre', '刚鬼 雷霆食人魔', '剛鬼サンダー・オーガ', 'Link Monster', 'Warrior', 'EARTH', NULL, 2200, NULL, '「刚鬼」怪兽2只以上 ①：只要这张卡在怪兽区域存在，回合玩家让以下效果适用。 ●自己主要阶段在通常召唤外加上只有1次，可以从手卡把1只怪兽往作为这张卡所连接区的自己场上召唤。 ②：这张卡所连接区的怪兽被战斗·效果破坏的场合才能发动。这张卡的攻击力上升400。'),
(97688360, 'Gouki Twistcobra', '刚鬼 锁喉眼镜蛇', '剛鬼ツイストコブラ', 'Effect Monster', 'Warrior', 'EARTH', 3, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只「刚鬼」怪兽解放，以自己场上1只「刚鬼」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升解放的怪兽的原本攻击力数值。这个效果在对方回合也能发动。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「刚鬼 固定眼镜蛇」以外的1张「刚鬼」卡加入手卡。'),
(63364266, 'Goyo Chaser', '御用追缉者', 'ゴヨウ・チェイサー', 'Synchro Monster', 'Warrior', 'EARTH', 5, 1900, 1000, '调整＋调整以外的怪兽1只以上 ①：这张卡的攻击力上升这张卡以外的场上的战士族·地属性的同调怪兽数量×300。 ②：这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽的攻击力变成一半在自己场上特殊召唤。'),
(58901502, 'Goyo Defender', '御用防御者', 'ゴヨウ・ディフェンダー', 'Synchro Monster', 'Warrior', 'EARTH', 3, 1000, 1000, '调整＋调整以外的怪兽1只以上 ①：1回合1次，自己场上的怪兽只有战士族·地属性的同调怪兽的场合才能发动。从额外卡组把1只「御用防御者」特殊召唤。 ②：这张卡被选择作为攻击对象时才能发动。这张卡的攻击力直到那次伤害步骤结束时上升这张卡以外的自己场上的战士族·地属性的同调怪兽数量×1000。'),
(59255742, 'Goyo Emperor', '御用皇帝', 'ゴヨウ・エンペラー', 'Fusion Monster', 'Warrior', 'EARTH', 10, 3300, 2500, '战士族·地属性的同调怪兽×2 ①：这张卡或者原本持有者是对方的自己怪兽战斗破坏对方怪兽送去墓地时才能发动。破坏的那只怪兽在自己场上特殊召唤。 ②：对方把怪兽特殊召唤时，把自己场上1只战士族·地属性的同调怪兽解放才能发动。得到那些怪兽的控制权。 ③：表侧表示的这张卡从场上离开的场合发动。自己场上的全部怪兽的控制权回归原本持有者。'),
(7391448, 'Goyo Guardian', '御用守护者', 'ゴヨウ・ガーディアン', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2800, 2000, '地属性调整＋调整以外的怪兽1只以上 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽在自己场上守备表示特殊召唤。'),
(84305651, 'Goyo King', '御用王', 'ゴヨウ・キング', 'Synchro Monster', 'Warrior', 'EARTH', 8, 2800, 2000, '调整＋调整以外的同调怪兽1只以上 ①：这张卡向对方怪兽攻击的攻击宣言时发动。这张卡的攻击力直到伤害步骤结束时上升自己场上的战士族·地属性的同调怪兽数量×400。 ②：这张卡战斗破坏对方怪兽送去墓地时，可以从以下效果选择1个发动。 ●破坏的那只怪兽在自己场上特殊召唤。 ●选对方场上1只表侧表示怪兽得到控制权。'),
(98637386, 'Goyo Predator', '御用捕食者', 'ゴヨウ・プレデター', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2400, 1200, '调整＋调整以外的怪兽1只以上 「御用捕食者」的效果1回合只能使用1次。 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽给与玩家的战斗伤害变成一半。'),
(53334471, 'Gozen Match', '御前比试', '御前試合', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方场上各自只能有1种类的属性的怪兽表侧表示存在。双方玩家在自身场上的表侧表示怪兽的属性是2种类以上的场合直到变成1种类为止必须送去墓地。'),
(52467217, 'Gozuki', '牛头鬼', '牛頭鬼', 'Effect Monster', 'Zombie', 'EARTH', 4, 1700, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组把1只不死族怪兽送去墓地。 ②：这张卡被送去墓地的场合，从自己墓地把「牛头鬼」以外的1只不死族怪兽除外才能发动。从手卡把1只不死族怪兽特殊召唤。'),
(79571449, 'Graceful Charity', '天使的施舍', '天使の施し', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组抽3张卡，之后从手卡选2张丢弃。'),
(74137509, 'Graceful Dice', '天使的骰子', '天使のサイコロ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：掷1次骰子。自己场上的怪兽的攻击力·守备力直到回合结束时上升出现的数目×100。'),
(98273947, 'Graceful Revival', '天使升降术', 'エンジェル・リフト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只2星以下的怪兽，攻击表示特殊召唤。这张卡不在场上存在时，那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。'),
(9032529, 'Graceful Tear', '天使之泪', '天使の涙', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：选自己1张手卡加入对方手卡。那之后，自己回复2000基本分。'),
(10992251, 'Gradius', '超时界战斗机 V型蛇', '超時空戦闘機ビック・バイパー', 'Normal Monster', 'Machine', 'LIGHT', 4, 1200, 800, '拥有后备仓库，能发挥各种能力的高性能战斗机。'),
(14291024, 'Gradius'' Option', '子机', 'オプション', 'Effect Monster', 'Machine', 'LIGHT', 1, -1, -1, '这张卡不能通常召唤。自己场上有「超时空战斗机 V形蛇」表侧表示存在的场合可以特殊召唤。这张卡特殊召唤的场合，必须选择自己场上表侧表示存在的1只「超时空战斗机 V形蛇」。这张卡的攻击力·守备力一直和选择的怪兽相同。选择的怪兽不在场上表侧表示存在时，这张卡破坏。'),
(20758643, 'Graff, Malebranche of the Burning Abyss', '彼岸恶鬼 格拉伯尼', '彼岸の悪鬼 グラバースニッチ', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1500, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合才能发动。从卡组把「彼岸的恶鬼 格拉菲亚卡内」以外的1只「彼岸」怪兽特殊召唤。'),
(21785144, 'Gragonith, Lightsworn Dragon', '光道龙 格拉古尼斯', 'ライトロード・ドラゴン グラゴニス', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2000, 1600, '这张卡的攻击力·守备力上升自己墓地存在的名字带有「光道」的怪兽卡种类×300的数值。这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这张卡在自己场上表侧表示存在的场合，每次自己的结束阶段，从卡组上面把3张卡送去墓地。'),
(13944422, 'Granadora', '贪食龙', 'グラナドラ', 'Effect Monster', 'Reptile', 'WATER', 4, 1900, 700, '这张卡召唤·反转召唤·特殊召唤成功时，自己回复1000基本分。这张卡被破坏送去墓地时，自己受到2000点伤害。'),
(38430673, 'Grand Convergence', '大十字', 'グランドクロス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上有「大宇宙」存在时才能发动。给与对方基本分300分伤害，场上的怪兽全部破坏。'),
(1637760, 'Grand Horn of Heaven', '升天之刚角笛', '昇天の剛角笛', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方主要阶段由对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。那之后，对方从卡组抽1张，对方主要阶段结束。'),
(51132012, 'Grand Knight of the Red Lotus', '大红莲魔斗士', '大紅蓮魔闘士', 'Effect Monster', 'Warrior', 'FIRE', 8, 2100, 1800, '这张卡不能通常召唤。「大红莲魔斗士」1回合1次在让效果怪兽以外的自己墓地最多3只怪兽回到卡组·额外卡组的场合才能从手卡·墓地特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升因为那次特殊召唤而回到卡组的通常怪兽数量×800。 ②：1回合1次，以场上1只怪兽和效果怪兽以外的自己墓地1只怪兽为对象才能发动。作为对象的场上的怪兽破坏，作为对象的墓地的怪兽特殊召唤。'),
(38057522, 'Grand Spiritual Art - Ichirin', '大灵术－「一轮」', '大霊術－「一輪」', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有守备力1500的魔法师族怪兽存在，对方发动的怪兽的效果1回合只有1次无效化。 ②：自己主要阶段才能发动。手卡1只魔法师族怪兽给对方观看，和那只怪兽相同属性而攻击力1500/守备力200的1只怪兽从卡组加入手卡，给人观看的怪兽回到卡组。'),
(13676474, 'Grand Tiki Elder', '假面咒术师 诅咒之喉', '仮面呪術師カースド・ギュラ', 'Normal Monster', 'Fiend', 'DARK', 4, 1500, 800, '以诅咒的咒文念杀对手的假面怪兽。'),
(83039729, 'Grandmaster of the Six Samurai', '六武众之师范', '六武衆の師範', 'Effect Monster', 'Warrior', 'EARTH', 5, 2100, 800, '①：「六武众的师范」在自己场上只能有1只表侧表示存在。 ②：自己场上有「六武众」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ③：这张卡被对方的效果破坏的场合，以自己墓地1只「六武众」怪兽为对象发动。那只怪兽加入手卡。'),
(44190146, 'Grandpa Demetto', '德梅特爷爷', 'デメット爺さん', 'Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己的「珂珑公主」1个超量素材取除才能发动。从自己墓地选最多2只攻击力或守备力是0的通常怪兽作为暗属性·8星怪兽守备表示特殊召唤。 ②：自己的超量怪兽把作为超量素材的通常怪兽取除来让效果发动的场合，以那1只超量怪兽和对方场上1只怪兽为对象才能发动。那只对方怪兽破坏，给与对方作为对象的超量怪兽的阶级×300伤害。'),
(35866404, 'Grandram', '大地运转兽', 'グランドラン', 'Effect Monster', 'Rock', 'EARTH', 4, NULL, 1400, '对方场上有超量怪兽存在的场合，这张卡可以从手卡表侧攻击表示特殊召唤。'),
(61468779, 'Grandsoil the Elemental Lord', '地灵神 格兰索尔', '地霊神グランソイル', 'Effect Monster', 'Beast-Warrior', 'EARTH', 8, 2800, 2200, '这张卡不能通常召唤。自己墓地的地属性怪兽是5只的场合才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功时，以自己或者对方的墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。 ②：表侧表示的这张卡从场上离开的场合，下次的自己回合的战斗阶段跳过。'),
(98898163, 'Grandtusk Dragon', '雄牙龙', 'グランドタスク・ドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 8, 1400, 2400, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以这张卡以外的场上最多2张卡为对象才能发动。那些卡破坏，这张卡的攻击力上升破坏数量×600。'),
(24915933, 'Granguignol the Dusk Dragon', '赫焉龙 格兰吉尼奥尔', '赫焉竜グランギニョル', 'Fusion Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2500, '「赫之圣女 卡尔特西娅」＋光·暗属性怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从卡组·额外卡组把1只6星以上的光·暗属性怪兽送去墓地。 ②：这张卡在怪兽区域或墓地存在的状态，对方发动的怪兽的效果让怪兽特殊召唤的场合，把这张卡除外才能发动。从卡组把1只「教导」怪兽或者从额外卡组把1只「死狱乡」怪兽特殊召唤。'),
(15545291, 'Granmarg the Mega Monarch', '刚地帝古兰玛古', '剛地帝グランマーグ', 'Effect Monster', 'Rock', 'EARTH', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。这张卡上级召唤成功时，选择场上盖放的最多2张卡破坏。这张卡把地属性怪兽解放作上级召唤成功的场合，那个时候的效果加上以下效果。 ●从卡组抽1张卡。'),
(60229110, 'Granmarg the Rock Monarch', '地帝古兰玛古', '地帝グランマーグ', 'Effect Monster', 'Rock', 'EARTH', 6, 2400, 1000, '①：这张卡上级召唤成功的场合，以场上盖放的1张卡为对象发动。盖放的那张卡破坏。'),
(84521924, 'GranSolfachord Coolia', '天籁音服和弦・克理娅', 'グランドレミコード・クーリア', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2700, NULL, '包含灵摆怪兽的怪兽2只以上 ①：这张卡的攻击力上升自己的额外卡组的表侧的灵摆怪兽数量×100。 ②：这张卡所连接区发动的灵摆怪兽的效果不会被无效化。 ③：1回合1次，对方把效果发动时才能发动。自己的灵摆区域1张灵摆刻度是奇数的「七音服」卡在作为这张卡所连接区的自己场上特殊召唤，那个发动无效。那之后，可以从卡组把1只灵摆刻度是偶数的「七音服」灵摆怪兽表侧加入额外卡组。'),
(37972500, 'GranSolfachord Musecia', '天籁音服和弦・缪斯西娅', 'グランドレミコード・ミューゼシア', 'Link Monster', 'Fairy', 'LIGHT', NULL, 1900, NULL, '灵摆怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只灵摆怪兽表侧表示加入额外卡组，把持有若那个灵摆刻度是奇数则为偶数的、是偶数则为奇数的灵摆刻度的1只表侧表示的灵摆怪兽从自己的额外卡组加入手卡。 ②：自己对「七音服」怪兽的灵摆召唤成功时，以那之内的1只为对象才能发动。和那只怪兽的灵摆刻度数值相同等级的1只「七音服」灵摆怪兽从卡组加入手卡。'),
(34230233, 'Grapha, Dragon Lord of Dark World', '暗黑界的龙神 格拉法', '暗黒界の龍神 グラファ', 'Effect Monster', 'Fiend', 'DARK', 8, 2700, 1800, '①：这张卡可以让「暗黑界的龙神 格拉法」以外的自己场上1只「暗黑界」怪兽回到持有者手卡，从墓地特殊召唤。 ②：这张卡被效果从手卡丢弃去墓地的场合，以对方场上1张卡为对象发动。那张对方的卡破坏。被对方的效果丢弃的场合，再把对方手卡随机选1张确认。那是怪兽的场合，可以把那只怪兽在自己场上特殊召唤。'),
(39552584, 'Grapha, Dragon Overlord of Dark World', '暗黑界的龙神王 格拉法', '暗黒界の龍神王 グラファ', 'Fusion Monster', 'Fiend', 'DARK', 10, 3200, 2300, '「暗黑界的龙神 格拉法」＋暗属性怪兽 这个卡名的①的效果1回合只能使用1次。 ①：对方把怪兽的效果·通常魔法·通常陷阱卡发动时才能发动。那个效果变成「对方选自身1张手卡丢弃」。 ②：融合召唤的这张卡因对方从场上离开的场合才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选1只「暗黑界的龙神 格拉法」特殊召唤。那之后，有手卡的玩家选自身1张手卡丢弃。'),
(32907538, 'Grapple Blocker', '造墙者', 'ウォールクリエイター', 'Effect Monster', 'Psychic', 'EARTH', 4, 1200, 2000, '这张卡召唤成功时，可以选择对方场上存在的1只怪兽。只要这张卡在场上表侧表示存在，选择的怪兽不能攻击也不能解放。这张卡的控制者在每次自己的结束阶段支付500基本分。或者不支付500基本分让这张卡破坏。'),
(2906250, 'Grappler', '捕猎蛇', 'グラップラー', 'Normal Monster', 'Reptile', 'WATER', 4, 1300, 1200, '狡猾的蛇。用又粗又长的身体勒紧对手的攻击必须注意！'),
(16632144, 'Grappler Angler', '顽强的钓师', '屈強の釣り師', 'Tuner Monster', 'Warrior', 'WATER', 1, 100, 100, '①：这张卡直接攻击给与对方战斗伤害时，以自己墓地1只怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(41249545, 'Grass Phantom', '幻灵草', 'グラスファントム', 'Effect Monster', 'Plant', 'WATER', 3, 1000, 1000, '这张卡的攻击力上升自己墓地存在的「幻灵草」的数量×500的数值。'),
(95166228, 'Grasschopper', '贵甲螳螂', 'ヴァリュアブル・アーマー', 'Gemini Monster', 'Insect', 'EARTH', 5, 2350, 1000, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●这张卡可以向对方场上的全部怪兽各作1次攻击。'),
(57270476, 'Grave Lure', '来自墓场的引诱', '墓場からの誘い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方卡组最上面1张卡表面向上放回卡组洗切。对方抽到那张卡时，那张卡直接送去墓地。'),
(83266092, 'Grave of the Super Ancient Organism', '超古代生物的墓场', '超古代生物の墓場', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，特殊召唤的6星以上的怪兽不能攻击宣言，双方不能把那些效果发动。'),
(40937767, 'Grave Ohja', '墓穴食人魔', 'グレイヴ・オージャ', 'Effect Monster', 'Rock', 'EARTH', 4, 1600, 1500, '只要自己场上存在里侧守备表示的怪兽，这张卡不能被选择为攻击对象。每次自己场上的怪兽反转召唤，给与对方300分伤害。'),
(11448373, 'Grave Protector', '墓场看守者', 'グレイヴ・キーパー', 'Effect Monster', 'Fiend', 'DARK', 4, NULL, 2000, '当这张卡在场上以表侧表示存在时，被战斗破坏的怪兽不再被送去墓地，直接回到持有者卡组。'),
(48343627, 'Grave Squirmer', '墓场蠕动者', 'グレイブ・スクワーマー', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '①：这张卡被战斗破坏送去墓地的场合，以场上1张卡为对象发动。那张卡破坏。'),
(82542267, 'Gravedigger Ghoul', '掘墓的食尸鬼', '墓掘りグール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方的墓地1张到2张的怪兽卡。选择的卡从游戏中除外。'),
(31548215, 'Gravedigger''s Trap Hole', '自掘空洞', '墓穴ホール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：手卡·墓地的怪兽或者除外中的怪兽的效果由对方发动时才能发动。那个效果无效，给与对方2000伤害。'),
(22134079, 'Gravekeeper''s Ambusher', '守墓的伏兵', '墓守の伏兵', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1700, NULL, '这张卡反转时，可以选择对方墓地1张卡回到卡组最下面。此外，反转过的这张卡被送去墓地的场合，可以选择自己墓地1张名字带有「王家长眠之谷」的卡加入手卡。这张卡的效果不会被「王家长眠之谷」的效果无效化。'),
(25262697, 'Gravekeeper''s Assailant', '守墓的暗杀者', '墓守の暗殺者', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1500, '「王家长眠之谷」在场上表侧表示存在时效果才能发动。这张卡攻击宣言时，可以变更对方场上存在的一只表侧表示怪兽的表示形式。'),
(99877698, 'Gravekeeper''s Cannonholder', '守墓的重炮手', '墓守の大筒持ち', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1400, 1200, '每祭掉自己场上1只名称中含有「守墓」的怪兽，给与对方基本分700分的伤害。使用这个效果的场合不能使用「守墓的重炮手」作为祭品。'),
(62473983, 'Gravekeeper''s Chief', '守墓之长', '墓守の長', 'Effect Monster', 'Spellcaster', 'DARK', 5, 1900, 1200, '这张卡在自己场上只能存在1张。只要这张卡在场上存在，自己的墓地不受「王家长眠之谷」效果的影响。这张卡祭品召唤成功的场合，可以从自己的墓地中特殊召唤1张名称中带有「守墓」的怪兽卡上场。'),
(17393207, 'Gravekeeper''s Commandant', '守墓的司令官', '墓守の司令官', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1600, 1500, '把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「王家长眠之谷」加入手卡。'),
(50712728, 'Gravekeeper''s Curse', '守墓的咒术师', '墓守の呪術師', 'Effect Monster', 'Spellcaster', 'DARK', 3, 800, 800, '这张卡召唤·反转召唤·特殊召唤时，给与对方玩家基本分500分的伤害。'),
(30213599, 'Gravekeeper''s Descendant', '守墓的末裔', '墓守の末裔', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1200, '把这张卡以外的自己场上表侧表示存在的1只名字带有「守墓」的怪兽解放才能发动。选择对方场上1张卡破坏。'),
(37101832, 'Gravekeeper''s Guard', '守墓的番兵', '墓守の番兵', 'Flip Effect Monster', 'Spellcaster', 'DARK', 4, 1000, 1900, '反转：对方场上1只怪兽回到持有者的手卡。'),
(21663205, 'Gravekeeper''s Headman', '守墓的神职', '墓守の神職', 'Effect Monster', 'Spellcaster', 'DARK', 3, 500, 1500, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合，以自己墓地1只4星「守墓」怪兽为对象才能发动。那只怪兽表侧攻击表示或者里侧守备表示特殊召唤。这个效果不受「王家长眠之谷」的效果影响。'),
(46955770, 'Gravekeeper''s Heretic', '守墓的异端者', '墓守の異端者', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 1500, '①：只要这张卡在怪兽区域存在，并在场上有「王家长眠之谷」存在，这张卡不受这张卡以外的效果影响。'),
(59494222, 'Gravekeeper''s Inscription', '守墓的刻印', '墓守の刻印', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己主要阶段1开始时才能发动。从以下效果选1个直到对方回合结束时适用。 ●双方不能把墓地的卡的效果发动。 ●双方不能把墓地的卡除外。 ●双方不能把墓地的怪兽特殊召唤。'),
(300201005, 'Gravekeeper''s Lot', NULL, NULL, 'Skill Card', 'Ishizu', NULL, NULL, NULL, NULL, NULL),
(85646474, 'Gravekeeper''s Nobleman', '守墓的使徒', '墓守の使徒', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1000, 1000, '这张卡被对方怪兽的攻击破坏送去墓地时，可以从卡组把「守墓的使徒」以外的1只名字带有「守墓」的怪兽里侧守备表示特殊召唤。'),
(25524823, 'Gravekeeper''s Oracle', '守墓的审神者', '墓守の審神者', 'Effect Monster', 'Spellcaster', 'DARK', 10, 2000, 1500, '这张卡也能把3只怪兽或者1只「守墓」怪兽解放表侧表示上级召唤。 ①：这张卡上级召唤成功时，可以从以下效果选择最多有为这张卡的上级召唤而解放的「守墓」怪兽的数量发动。 ●这张卡的攻击力上升因为这张卡的上级召唤而解放的怪兽的等级合计×100。 ●对方场上的里侧表示怪兽全部破坏。 ●对方场上的全部怪兽的攻击力·守备力下降2000。'),
(3381441, 'Gravekeeper''s Priestess', '守墓的巫女', '墓守の巫女', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1000, 1500, '只要这张卡在场上表侧表示存在，场地变成「王家长眠之谷」。场地魔法卡表侧表示存在的场合，这个效果不适用。此外，只要这张卡在场上表侧表示存在，场上的名字带有「守墓」的怪兽的攻击力·守备力上升200。'),
(93023479, 'Gravekeeper''s Recruiter', '守墓的召唤师', '墓守の召喚師', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1200, 1500, '这张卡从自己场上送去自己墓地时，从自己的卡组把1只守备力1500以下的名字带有「守墓」的怪兽加入手卡。'),
(16762927, 'Gravekeeper''s Servant', '守墓的使魔', '墓守の使い魔', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方若不把卡组最上面的1张卡送去墓地，则不能攻击宣言。'),
(58139128, 'Gravekeeper''s Shaman', '守墓的祈祷师', '墓守の祈祷師', 'Effect Monster', 'Spellcaster', 'DARK', 6, 1500, 1500, '这张卡的守备力上升自己墓地的名字带有「守墓」的怪兽数量×200的数值。只要这张卡在场上表侧表示存在，名字带有「守墓」的怪兽以外的墓地发动的效果怪兽的效果无效化。此外，「王家长眠之谷」在场上存在的场合，对方不能把场地魔法卡发动，场地魔法卡不会被对方的效果破坏。'),
(63695531, 'Gravekeeper''s Spear Soldier', '守墓的长枪兵', '墓守の長槍兵', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1000, '这张卡攻击守备表示的怪兽时，若这张卡的攻击力高于守备怪兽的守备力，则超过部分的数值对对方造成战斗伤害。'),
(58657303, 'Gravekeeper''s Spiritualist', '守墓的灵术师', '墓守の霊術師', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1500, '这个卡名的效果1回合只能使用1次。 ①：场上有「王家长眠之谷」存在的场合才能发动。魔法师族融合怪兽卡决定的包含场上的这张卡的融合素材怪兽从自己的手卡·场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(24317029, 'Gravekeeper''s Spy', '守墓的侦察者', '墓守の偵察者', 'Flip Effect Monster', 'Spellcaster', 'DARK', 4, 1200, 2000, '反转：从自己的卡组中特殊召唤1张攻击力1500以下名称中带有「守墓」的怪兽卡。'),
(99523325, 'Gravekeeper''s Stele', '守墓的石板', '墓守の石版', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的2只名字带有「守墓」的怪兽加入手卡。这个效果不会被「王家长眠之谷」的效果无效化。'),
(79206925, 'Gravekeeper''s Supernaturalist', '守墓的异能者', '墓守の異能者', 'Fusion Monster', 'Spellcaster', 'DARK', 7, 2000, 2000, '「守墓」怪兽×2 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力·守备力上升作为这张卡的融合素材的怪兽的原本等级合计×100。 ②：只要场上有「王家长眠之谷」存在，这张卡以及自己的场地区域的卡不会被效果破坏。 ③：自己主要阶段才能发动。这个回合的结束阶段，从卡组把1只「守墓」怪兽或者1张「王家长眠之谷」卡加入手卡。'),
(98715423, 'Gravekeeper''s Trap', '守墓的陷阱', '墓守の罠', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己墓地有「现世与冥界的逆转」存在，对方不能把墓地的卡的效果发动，不能把墓地的怪兽特殊召唤。 ②：双方的主要阶段，丢弃1张手卡才能发动。从卡组把1只「守墓」怪兽或者天使族·地属性怪兽加入手卡。 ③：这张卡表侧表示存在的场合，对方抽卡阶段的抽卡前，宣言1个卡名发动。把通常抽卡的卡确认，宣言的卡的场合，送去墓地。'),
(99690140, 'Gravekeeper''s Vassal', '守墓的从者', '墓守の従者', 'Effect Monster', 'Spellcaster', 'DARK', 3, 700, 500, '这张卡给与对方造成的战斗伤害，算作这张卡的效果造成的伤害使用。'),
(3825890, 'Gravekeeper''s Visionary', '守墓的大神官', '墓守の大神官', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2000, 1800, '这张卡可以把1只名字带有「守墓」的怪兽解放作召唤。这张卡的攻击力上升自己墓地存在的名字带有「守墓」的怪兽数量×200的数值。场上表侧表示存在的这张卡被破坏的场合，可以作为代替从手卡把1只名字带有「守墓」的怪兽丢弃。'),
(26084285, 'Gravekeeper''s Watcher', '守墓的监视者', '墓守の監視者', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1000, 1000, '对方发动效果中含有丢弃对方自己手卡的卡的效果时，可以将这张卡从手卡送去墓地，那张卡的发动与效果无效并且破坏。'),
(48135190, 'Gravelstorm', '砂石飓风', '砂利ケーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己以及对方场上存在的魔法·陷阱卡各1张发动。选择的卡回到持有者手卡。'),
(61705417, 'Graverobber', '盗墓者', '墓荒らし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方墓地的1张魔法卡，直到回合结束时可以作为自己的手卡使用。使用那张魔法卡的场合，受到2000分伤害。'),
(33737664, 'Graverobber''s Retribution', '盗墓者的报应', '墓荒らしの報い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段，每存在1只除外的对方怪兽，对方受到100分的伤害。'),
(27094595, 'Graveyard and the Hand of Invitation', '招手的墓场', '手招きする墓場', 'Normal Monster', 'Zombie', 'DARK', 3, 700, 900, '给予死者进一步提升的力量，引诱生者步向死亡的墓场。'),
(98596596, 'Graveyard of Wandering Souls', '灵魂游荡的墓场', '魂のさまよう墓場', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡已在魔法与陷阱区域存在的状态，自己场上的怪兽被战斗破坏送去墓地的场合发动。在自己场上把1只「火之玉衍生物」（炎族·炎·1星·攻/守100）特殊召唤。 ②：这张卡已在魔法与陷阱区域存在的状态，自己的手卡·场上的怪兽被对方的效果送去墓地的场合发动。把最多有那些怪兽数量的「火之玉衍生物」尽可能在自己场上特殊召唤。'),
(9391354, 'Gravi-Crush Dragon', '重力击龙', 'グラビ・クラッシュドラゴン', 'Effect Monster', 'Dragon', 'DARK', 6, 2400, 1200, '①：把自己场上1张表侧表示的永续魔法卡送去墓地，以对方场上1只怪兽为对象才能发动。那只对方怪兽破坏。'),
(29216198, 'Gravitic Orb', '重力球', 'グラビティ・ボール', 'Flip Effect Monster', 'Fiend', 'DARK', 3, 1100, 700, '反转：对方场上存在的表侧表示怪兽全部的表示形式改变。'),
(32022366, 'Gravity Axe - Grarl', '重力之斧-咆哮', '重力の斧－グラール', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备这张卡的怪兽攻击力上升500点。只要这张卡在场上存在，对方场上的怪兽不能改变表示形式。'),
(37930737, 'Gravity Balance', '重力均衡', '重力均衡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「G石人」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地的怪兽以及除外的自己怪兽之中以2只地属性同名怪兽为对象才能发动。那2只攻击力·守备力变成0，效果无效守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。 ②：自己场上的「G石人」怪兽被战斗或者对方的效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(56931015, 'Gravity Behemoth', '重力巨兽', 'グラヴィティ・ベヒモス', 'Effect Monster', 'Beast', 'DARK', 6, 2300, 2000, '场上没有卡存在的场合，这张卡可以不用解放作召唤。这个效果在先攻第1回合不能使用。这张卡可以作为攻击的代替把场上存在的场地魔法卡破坏。'),
(85742772, 'Gravity Bind', '超重力网', 'グラヴィティ・バインド－超重力の網－', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '场上的4星以上的怪兽不能攻击。'),
(35220244, 'Gravity Blaster', '重力炮', '重力砲', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族怪兽才能装备。1回合1次，可以让装备怪兽的攻击力上升400。此外，装备怪兽和对方怪兽进行战斗的场合，只在战斗阶段内那只对方怪兽的效果无效化。'),
(7811875, 'Gravity Collapse', '重力崩坏', '重力崩壊', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方把怪兽召唤·反转召唤·特殊召唤之际，把自己场上1只表侧表示的同调怪兽送去墓地才能发动。那个无效，那些怪兽破坏。这个回合，对方不能把怪兽召唤·反转召唤·特殊召唤。'),
(23656668, 'Gravity Controller', '重力御者', 'グラビティ・コントローラー', 'Link Monster', 'Psychic', 'DARK', NULL, 1000, NULL, '连接怪兽以外的额外怪兽区域的怪兽1只 这张卡在连接召唤的回合不能作为连接素材。 ①：额外怪兽区域的这张卡不会被和主要怪兽区域的怪兽的战斗破坏。 ②：这张卡和额外怪兽区域的对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽和这张卡回到卡组。'),
(69319869, 'Gravity Lash', '钝重', '鈍重', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降那只怪兽的守备力数值。'),
(44035031, 'Gravity Warrior', '重力战士', 'グラヴィティ・ウォリアー', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2100, 1000, '调整＋调整以外的怪兽1只以上 这张卡同调召唤成功时，这张卡的攻击力上升对方场上表侧表示存在的怪兽数量×300的数值。1回合1次，对方的战斗阶段时选择对方场上守备表示存在的1只怪兽才能发动。选择的怪兽变成表侧攻击表示。这个回合那只怪兽可以攻击的场合必须作出攻击。'),
(29618570, 'Gray Wing', '灰翼龙', 'グレイ・ウイング', 'Effect Monster', 'Dragon', 'WIND', 3, 1300, 700, '在主要阶段一丢弃1张手卡。这张卡在那个回合的战斗阶段中可以2次攻击。'),
(66451379, 'Graydle Alligator', '灰篮短吻鳄', 'グレイドル・アリゲーター', 'Effect Monster', 'Aqua', 'WATER', 3, 500, 1500, '①：自己的怪兽区域的这张卡被战斗或者魔法卡的效果破坏送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。这张卡当作装备卡使用给那只对方怪兽装备。 ②：这张卡的效果让这张卡装备中的场合，得到装备怪兽的控制权。这张卡从场上离开时装备怪兽破坏。'),
(93445074, 'Graydle Cobra', '灰篮眼镜蛇', 'グレイドル・コブラ', 'Effect Monster', 'Aqua', 'WATER', 3, 1000, 1000, '①：自己的怪兽区域的这张卡被战斗或者陷阱卡的效果破坏送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。这张卡当作装备卡使用给那只对方怪兽装备。 ②：这张卡的效果让这张卡装备中的场合，得到装备怪兽的控制权。这张卡从场上离开时装备怪兽破坏。'),
(84442536, 'Graydle Combat', '灰篮战斗', 'グレイドル・コンバット', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：只以自己场上的「灰篮」怪兽1只为对象的怪兽的效果·魔法·陷阱卡发动时，可以从以下效果选择1个发动。 ●那个效果变成「作为对象的1只怪兽破坏」。 ●那个发动无效并破坏。'),
(52145422, 'Graydle Dragon', '灰篮龙', 'グレイドル・ドラゴン', 'Synchro Monster', 'Aqua', 'WATER', 8, 3000, 2000, '水族调整＋调整以外的怪兽1只以上 「灰篮龙」的①②的效果1回合各能使用1次。 ①：这张卡同调召唤成功时，以最多有那些作为同调素材的水属性怪兽数量的对方场上的卡为对象才能发动。那些卡破坏。 ②：这张卡被战斗·效果破坏送去墓地的场合，以这张卡以外的自己墓地1只水属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(29834183, 'Graydle Eagle', '灰篮鹰', 'グレイドル・イーグル', 'Effect Monster', 'Aqua', 'WATER', 3, 1500, 500, '①：自己的怪兽区域的这张卡被战斗或者怪兽的效果破坏送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。这张卡当作装备卡使用给那只对方怪兽装备。 ②：这张卡的效果让这张卡装备中的场合，得到装备怪兽的控制权。这张卡从场上离开时装备怪兽破坏。'),
(2759860, 'Graydle Impact', '灰篮撞击', 'グレイドル・インパクト', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「灰篮撞击」的①②的效果1回合只能有1次使用其中任意1个。 ①：以这张卡以外的自己场上1张「灰篮」卡和对方场上1张卡为对象才能把这个效果发动。那些卡破坏。 ②：自己结束阶段才能把这个效果发动。从卡组把1张「灰篮」卡加入手卡。'),
(49966595, 'Graydle Parasite', '灰篮寄生体', 'グレイドル・パラサイト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「灰篮寄生体」的①②的效果1回合各能使用1次。 ①：对方怪兽的直接攻击宣言时才能把这个效果发动。自己场上没有怪兽存在的场合，从卡组把1只「灰篮」怪兽攻击表示特殊召唤。 ②：自己的「灰篮」怪兽的直接攻击宣言时，以对方墓地1只怪兽为对象才能发动。对方场上没有怪兽存在的场合，那只怪兽在对方场上特殊召唤。'),
(20056760, 'Graydle Slime', '灰篮史莱姆', 'グレイドル・スライム', 'Tuner Monster', 'Aqua', 'WATER', 5, NULL, 2000, '「灰篮史莱姆」的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，以自己场上2张「灰篮」卡为对象才能发动。那些卡破坏，这张卡特殊召唤。 ②：这张卡的①的效果特殊召唤成功时，以自己墓地1只「灰篮」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(80250319, 'Graydle Slime Jr.', '小灰篮史莱姆', 'グレイドル・スライムJr.', 'Tuner Monster', 'Aqua', 'WATER', 2, NULL, 2000, '①：这张卡召唤成功时，以自己墓地1只「灰篮」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以把和这个效果特殊召唤的怪兽相同等级的1只水族怪兽从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是水属性怪兽不能特殊召唤。 ②：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只「灰篮」怪兽特殊召唤。'),
(75361204, 'Graydle Split', '灰篮分裂', 'グレイドル・スプリット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「灰篮分裂」的②的效果1回合只能使用1次。 ①：以自己场上1只怪兽为对象才能把这张卡发动。这张卡当作攻击力上升500的装备卡使用给那只怪兽装备。 ②：自己主要阶段，把这张卡的效果装备的这张卡送去墓地才能发动。这张卡装备过的怪兽破坏，从卡组把2只「灰篮」怪兽特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(11813953, 'Great Angus', '大型肉畜', 'グレート・アンガス', 'Normal Monster', 'Beast', 'FIRE', 4, 1800, 600, '非常凶暴的怪兽。据说从来没人看见过其温顺一面的姿态。'),
(55691901, 'Great Bill', '大嘴', 'グレード・ビル', 'Normal Monster', 'Beast', 'EARTH', 4, 1250, 1300, '拥有可以吞下一切的大嘴。'),
(88989706, 'Great Dezard', '大神官 迪·扎德', '大神官デ・ザード', 'Effect Monster', 'Spellcaster', 'DARK', 6, 1900, 2300, '根据战斗破坏怪兽的次数得到下面的效果： ●1次：只要这张卡在场上表侧表示存在，以这张卡为对象的魔法·陷阱卡的发动和效果无效并破坏。 ●2次：可以把这张卡做祭品，从自己的手卡·卡组选1只「不死王 巫妖」特殊召唤到场上。'),
(2356994, 'Great Long Nose', '伟大天狗', '偉大天狗', 'Spirit Monster', 'Beast-Warrior', 'DARK', 5, 1900, 1700, '这张卡不能特殊召唤。召唤·反转回合的结束阶段时回到主人的手卡。这张卡给与对方玩家战斗伤害的场合，跳过下次的对方回合的战斗阶段。'),
(47942531, 'Great Maju Garzett', '伟大魔兽 加泽特', '偉大魔獣 ガーゼット', 'Effect Monster', 'Fiend', 'DARK', 6, NULL, NULL, '这张卡的攻击力变成祭品召唤时作为祭品的1只怪兽的原本攻击力2倍的数值。'),
(54622031, 'Great Mammoth of Goldfine', '金色魔象', '金色の魔象', 'Fusion Monster', 'Zombie', 'DARK', 6, 2200, 1800, '「美杜莎的亡灵」＋「龙僵尸」'),
(14141448, 'Great Moth', '大飞蛾', 'グレート・モス', 'Effect Monster', 'Insect', 'EARTH', 8, 2600, 2500, '装备了「进化之茧」的「飞蛾宝宝」4回合后（用自己的回合来数）作祭品来特殊召唤。'),
(10809984, 'Great Phantom Thief', '世纪大盗', '世紀の大泥棒', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1000, 1000, '每当这张卡给与对方战斗伤害时，宣言1张卡的名字。检视对方手卡，若其中有被宣言名字的卡，则将其全部扔进墓地。'),
(75292259, 'Great Poseidon Beetle', '海神独角仙', 'ポセイドン・オオカブト', 'Effect Monster', 'Insect', 'EARTH', 7, 2500, 2300, '这张卡向对方场上表侧攻击表示存在的怪兽攻击，那只怪兽没被战斗破坏的场合，可以向同只怪兽继续攻击。这个效果1回合可以使用最多2次。'),
(60884672, 'Great Sand Sea - Gold Golgonda', '大砂海 黄金的戈尔钢达', '大砂海ゴールド・ゴルゴンダ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：场上的「护宝炮妖」超量怪兽的攻击力上升1000。 ②：自己场上没有「护宝炮妖」超量怪兽存在的场合，从手卡丢弃1张「护宝炮妖」卡才能发动。从额外卡组把1只「护宝炮妖」超量怪兽特殊召唤。 ③：自己场上的表侧表示的超量怪兽因效果从场上离开的场合，以对方场上1只怪兽为对象才能发动。这个回合，那只怪兽不能攻击。'),
(63176202, 'Great Shogun Shien', '大将军 紫炎', '大将軍 紫炎', 'Effect Monster', 'Warrior', 'FIRE', 7, 2500, 2400, '自己场上有名字带有「六武众」的怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。只要这张卡在场上表侧表示存在，对方1回合只能有1次把魔法·陷阱卡发动。此外，场上表侧表示存在的这张卡被破坏的场合，可以作为代替把自己场上表侧表示存在的1只名字带有「六武众」的怪兽破坏。'),
(27796375, 'Great Sorcerer of the Nekroz', '影灵衣的大魔道士', '影霊衣の大魔道士', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1500, 800, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡被效果解放的场合才能发动。从卡组把1只魔法师族「影灵衣」仪式怪兽加入手卡。 ②：这张卡被除外的场合才能发动。从卡组把「影灵衣大魔道士」以外的1只「影灵衣」怪兽送去墓地。'),
(92736188, 'Great Spirit', '伟大的神灵', 'グレート・スピリット', 'Effect Monster', 'Rock', 'EARTH', 4, 500, 1500, '这张卡1回合只有1次可以变成里侧守备表示。这张卡反转召唤成功时，选择场上1只地属性怪兽才能发动。选择的地属性怪兽的原本攻击力和原本守备力直到结束阶段时交换。'),
(13429800, 'Great White', '大白鲨', 'グレート・ホワイト', 'Normal Monster', 'Fish', 'WATER', 4, 1600, 800, '巨大的白鲨，若被咬到绝对无法脱身。'),
(7614732, 'Greater Polymerization', '大融合', '大融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个效果融合召唤的场合，融合素材怪兽必须是3只以上。这个效果特殊召唤的怪兽得到以下效果。 ●这张卡不会被效果破坏。 ●这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(90512490, 'Greatfly', '超刃蝇', 'グレートフライ', 'Link Monster', 'Insect', 'WIND', NULL, 1400, NULL, '风属性怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：场上的风属性怪兽的攻击力·守备力上升500，地属性怪兽的攻击力·守备力下降400。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1只风属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(89405199, 'Greed', '欲望的幻象', 'グリード', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '因卡的效果进行抽卡的玩家，在那个回合的结束阶段终了时受到因卡的效果抽的卡的数量×500的伤害。'),
(3972721, 'Greed Grado', '强欲之喜', 'グリード・グラード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己把对方场上表侧表示存在的同调怪兽战斗或者卡的效果破坏的回合才能发动。从自己卡组抽2张卡。'),
(76593718, 'Greed Jar', '强欲之瓮', '強欲なポッド', 'Flip Effect Monster', 'Rock', 'EARTH', 3, 700, 800, '这个卡名的效果1回合只能使用1次。 ①：这张卡反转的场合发动。以下效果各适用。 ●把最多有对方场上的卡数量的卡从自己卡组上面翻开，从那之中选1张加入手卡，剩余送去墓地。 ●把最多有从额外卡组特殊召唤的对方场上的怪兽数量的怪兽从自己的额外卡组送去墓地。'),
(50263751, 'Greed Quasar', '贪婪类星体', 'グリード・クエーサー', 'Effect Monster', 'Fiend', 'DARK', 7, -1, -1, '①：这张卡的原本的攻击力·守备力变成这张卡的等级×300。 ②：只要这张卡在怪兽区域存在，这张卡的等级上升这张卡战斗破坏的怪兽的原本等级数值。'),
(51570882, 'Greedy Venom Fusion Dragon', '贪婪猛毒结合龙', 'グリーディー・ヴェノム・フュージョン・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 10, 3300, 2500, '「捕食植物」怪兽＋原本等级是8星以上的暗属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：1回合1次，以场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力变成0，效果无效化。 ②：这张卡被破坏送去墓地的场合发动。场上的怪兽全部破坏。那之后，可以把自己墓地1只8星以上的暗属性怪兽除外把这张卡从墓地特殊召唤。'),
(46668237, 'Green Baboon, Defender of the Forest', '森之番人 绿狒狒', '森の番人グリーン・バブーン', 'Effect Monster', 'Beast', 'EARTH', 7, 2600, 1800, '①：这张卡在手卡·墓地存在，自己场上的表侧表示的兽族怪兽被效果破坏送去墓地时，支付1000基本分才能发动。这张卡特殊召唤。'),
(52182715, 'Green Duston', '绿尘妖', 'グリーン・ダストン', 'Effect Monster', 'Fiend', 'WIND', 1, NULL, 1000, '这张卡不能解放，也不能作为融合·同调·超量召唤的素材。场上的这张卡被破坏时，这张卡的控制者选择自己场上1张魔法·陷阱卡回到持有者手卡。「绿尘妖」在自己场上只能有1只表侧表示存在。'),
(41172955, 'Green Gadget', '绿色小工具', 'グリーン・ガジェット', 'Effect Monster', 'Machine', 'EARTH', 4, 1400, 600, '①：这张卡召唤·特殊召唤成功时才能发动。从卡组把1只「红色零件」加入手卡。'),
(15198996, 'Green Ninja', '稚绿忍者', '若い忍者', 'Effect Monster', 'Warrior', 'WIND', 2, 600, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有怪兽表侧表示特殊召唤的场合，以那之内的1只为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽变成里侧守备表示。 ②：这张卡从手卡·场上送去墓地的场合，以场上1只怪兽为对象才能发动。那只怪兽变成表侧攻击表示或里侧守备表示。'),
(22910685, 'Green Phantom King', '绿树之灵王', '緑樹の霊王', 'Normal Monster', 'Plant', 'EARTH', 3, 500, 1600, '居住在被绿树包围的地方，统治森林的年轻国王。');